var ProtoMessage = function () {
    //原始buffer, iRet告诉框架是否解析成功(0:表示成功, 其他失败, rpc_call会抛出error, message由sResultDesc指定)
    //
    this.origin = {
        iRet : 0,
        sBuffer : undefined,
        sResultDesc  : "",        
    };

    this.sFuncName = undefined;
    this.iRequestId = undefined;
    this.appBuffer = undefined;
    this.property = undefined; //业务附加数据
    this.iTimeout = 0; //客户端超时时间，以利用cpp server端队列超时
    //    this.iResultCode  =  0;
    //    this.sResultDesc  = "";
};

// module.exports.Request  = ProtoMessageRequest;
// module.exports.Response = ProtoMessageResponse;
module.exports.ProtoMessage  = ProtoMessage;
